/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AddPdfHighlightInput = {
  cardId?: string | null | undefined;
  /** YELLOW when left out */
  color?: HighlightColor | null | undefined;
  comment?: string | null | undefined;
  /** A PDF attached to the note */
  fileId: string;
  kind: HighlightKind;
  noteId: string;
  page: number;
  quote?: string | null | undefined;
  /** One rectangle for an AREA; up to 100 lines for TEXT */
  rects: Array<Array<number>>;
};

export type AppealModerationInput = {
  entityId: string;
  entityType: ReportEntityType;
  message: string;
};

/** A card as the client has it. Ids are UUIDs the client makes, so cards created offline keep their id. */
export type CardInput = {
  content: unknown;
  id: string;
  position: string;
  type: CardType;
};

export type CardOpInput = {
  /** The card's revision the client last saw; omitted for new cards */
  baseRevision?: number | null | undefined;
  content?: unknown;
  id: string;
  kind: CardOpKind;
  position?: string | null | undefined;
  type?: CardType | null | undefined;
};

export type CardOpKind =
  /** Remove the card; send `baseRevision` */
  | 'DELETE'
  /** Change only `position` */
  | 'MOVE'
  /** Create the card, or change it; send `baseRevision` when changing */
  | 'UPSERT';

export type CardOpStatus =
  | 'APPLIED'
  /** Applied, but the card had changed on another device since baseRevision: that version is kept in `conflictVersion` */
  | 'APPLIED_WITH_CONFLICT'
  /** Not applied: the card was deleted, or changed elsewhere before this delete */
  | 'REJECTED';

/** The sixteen card types (§4.1); content is validated per type (@lvn/contracts/validation) */
export type CardType =
  | 'audio'
  | 'callout'
  | 'checklist'
  | 'code'
  | 'diagram'
  | 'file'
  | 'flashcard'
  | 'heading'
  | 'image'
  | 'markdown'
  | 'question'
  | 'quiz'
  | 'quote'
  | 'table'
  | 'text'
  | 'video';

/** After a provider sign-in (no signUp call): the same details, collected once */
export type CompleteRegistrationInput = {
  acceptedTermsVersion: string;
  dateOfBirth: string;
  displayName: string;
  institutionalEmail?: string | null | undefined;
};

export type ConnectionDirection =
  /** They asked the viewer */
  | 'INCOMING'
  /** The viewer asked them */
  | 'OUTGOING';

export type ConnectionRequestInput = {
  requestId: string;
};

export type CreateNoteInput = {
  cards?: Array<CardInput> | null | undefined;
  folderId?: string | null | undefined;
  /** Made on the device for a note written offline (a UUIDv7, §13.2); leave out to let the server choose */
  id?: string | null | undefined;
  kind?: NoteKind | null | undefined;
  tagNames?: Array<string> | null | undefined;
  title?: string | null | undefined;
  topicIds?: Array<string> | null | undefined;
};

export type CreateUploadIntentInput = {
  /** Shown to people; never part of the storage key */
  fileName: string;
  mimeType: string;
  parentId?: string | null | undefined;
  purpose: FilePurpose;
  sizeBytes: number;
};

export type DataExportStatus =
  | 'EXPIRED'
  | 'FAILED'
  | 'PENDING'
  | 'READY';

/** Fixed error vocabulary (§6.2) */
export type ErrorCode =
  | 'CONFLICT'
  | 'FORBIDDEN'
  | 'INTERNAL'
  | 'NOT_FOUND'
  | 'RATE_LIMITED'
  | 'UNAUTHENTICATED'
  | 'VALIDATION';

/** What an upload is for: AVATAR, VERIFICATION_DOCUMENT, and ATTACHMENT (a picture, video, audio or PDF for a note you can edit, given as parentId). Other purposes arrive with their features. */
export type FilePurpose =
  | 'ATTACHMENT'
  | 'AVATAR'
  | 'COVER'
  | 'EXPORT'
  | 'IMPORT'
  | 'VERIFICATION_DOCUMENT'
  | 'VOICE_NOTE';

export type GlobalRole =
  | 'PLATFORM_ADMIN'
  | 'STUDENT'
  | 'TEACHER';

export type HighlightColor =
  | 'BLUE'
  | 'GREEN'
  | 'PINK'
  | 'PURPLE'
  | 'YELLOW';

export type HighlightKind =
  /** An area of the page, such as a figure or a formula */
  | 'AREA'
  /** A passage of text */
  | 'TEXT';

export type InstitutionalEmailStatus =
  /** A code was sent to the address and not yet entered */
  | 'CODE_SENT'
  /** Confirmed; the account is verified by it */
  | 'CONFIRMED'
  /** No college or organisation email yet */
  | 'NONE'
  /** Confirmed, but the domain waits for platform-admin review before it verifies the account */
  | 'PENDING_REVIEW';

export type LegacyImportStatus =
  | 'AVAILABLE'
  | 'CLAIMED'
  | 'DECLINED'
  | 'NOT_FOUND';

export type MarkNotificationsReadInput = {
  all?: boolean | null | undefined;
  /** These notifications; ignored when all is true */
  ids?: Array<string> | null | undefined;
};

export type ModerateContentInput = {
  action: ModerationActionType;
  entityId: string;
  entityType: ReportEntityType;
  /** Required for HIDE, REMOVE and WARN: the author is told */
  reason?: string | null | undefined;
};

/** APPROVE frees a held note; HIDE and REMOVE take it off for everyone but its author; DISMISS closes reports; WARN tells the author. SUSPEND is not available yet. */
export type ModerationActionType =
  | 'APPROVE'
  | 'DISMISS'
  | 'HIDE'
  | 'REMOVE'
  | 'SUSPEND'
  | 'WARN';

export type ModerationState =
  | 'HIDDEN'
  | 'OK'
  | 'PENDING_REVIEW'
  | 'REMOVED';

/** OWNER and EDITOR work on the draft; READER sees the published version (§4.3) */
export type NoteAccess =
  | 'EDITOR'
  | 'OWNER'
  | 'READER';

export type NoteFilter = {
  /** Notes in this folder (not its subfolders) */
  folderId?: string | null | undefined;
  kind?: NoteKind | null | undefined;
  tagId?: string | null | undefined;
  topicId?: string | null | undefined;
  /** The trash instead of the live notes */
  trashed?: boolean | null | undefined;
  /** Notes in no folder */
  unfiled?: boolean | null | undefined;
};

export type NoteImportStatus =
  | 'DONE'
  | 'FAILED'
  | 'NEEDS_CONFIRMATION'
  | 'PENDING'
  | 'RUNNING';

/** What a note is presented as (ADR-0014, ADR-0015). Phase 2 creates NOTE only. */
export type NoteKind =
  | 'BLOG'
  | 'NOTE'
  | 'POST'
  | 'PROJECT';

export type NoteShareRole =
  | 'EDITOR'
  | 'VIEWER';

/** DIRECT: shared with this person; CONNECTIONS: a connection of the owner, who shares with all of them (ADR-0044) */
export type NoteShareSource =
  | 'CONNECTIONS'
  | 'DIRECT';

/** PUBLISHED: what readers see. CONFLICT: the losing side of a card edited on two devices. DRAFT: the draft before a restore. */
export type NoteVersionKind =
  | 'CONFLICT'
  | 'DRAFT'
  | 'PUBLISHED';

export type NotificationCategory =
  | 'CLASSROOM_POST'
  | 'COMMENT'
  | 'CONNECTION'
  | 'DATA_EXPORT'
  | 'DOUBT'
  | 'FOLLOW'
  | 'FORK_PUBLISHED'
  | 'JOIN_DECISION'
  | 'JOIN_REQUEST'
  | 'MENTOR_INVITE'
  | 'NOTES_IMPORT'
  | 'QUIZ_PUBLISHED'
  | 'REVISION_REMINDER'
  | 'SHARE'
  | 'STREAK_AT_RISK'
  | 'VERIFICATION';

/** Authorization Code + PKCE: the code from the provider's redirect and the verifier the client generated */
export type OAuthExchangeInput = {
  code: string;
  codeVerifier: string;
  provider: OAuthProvider;
  redirectUri: string;
};

/** Providers exchanged through oauthExchange. Google uses signInWithGoogle (ADR-0007). */
export type OAuthProvider =
  | 'GITHUB'
  | 'LINKEDIN';

export type PdfConversionStatus =
  | 'DONE'
  | 'FAILED'
  /** Making the cards */
  | 'MAPPING'
  /** Reading the layout, tables, pictures and scanned pages */
  | 'PARSING'
  | 'QUEUED'
  /** Counting the pages */
  | 'TRIAGE';

export type PersonInput = {
  userId: string;
};

export type ReportContentInput = {
  /** What is wrong, in the reporter's words (at most 1,000 characters) */
  details?: string | null | undefined;
  entityId: string;
  entityType: ReportEntityType;
  reason: ReportReason;
};

export type ReportEntityType =
  | 'NOTE'
  | 'USER';

export type ReportReason =
  | 'COPYRIGHT'
  | 'HARASSMENT'
  | 'HATE'
  | 'OTHER'
  | 'SELF_HARM'
  | 'SEXUAL'
  | 'SPAM';

export type RespondToConnectionRequestInput = {
  accept: boolean;
  requestId: string;
};

export type SignInInput = {
  email: string;
  password: string;
};

/**
 * Registration (ADR-0017, ADR-0019): date of birth is required (YYYY-MM-DD). A college or organisation email is
 * optional; it receives a 6-digit code. `acceptedTermsVersion` must be Query.termsVersion.
 */
export type SignUpInput = {
  acceptedTermsVersion: string;
  dateOfBirth: string;
  displayName: string;
  email: string;
  institutionalEmail?: string | null | undefined;
  password: string;
};

export type TeacherSkillInput = {
  /** At most 500 characters */
  detail?: string | null | undefined;
  kind: TeacherSkillKind;
  /** At most 120 characters */
  name: string;
};

export type TeacherSkillKind =
  | 'EXPERIENCE'
  | 'QUALIFICATION'
  | 'SKILL';

export type TopicOrigin =
  | 'CURATED'
  | 'PROPOSED';

/** Omitted fields stay as they are; `parentId: null` moves the folder to the top level */
export type UpdateFolderInput = {
  id: string;
  name?: string | null | undefined;
  parentId?: string | null | undefined;
};

/**
 * One save of the draft (autosave). Title, folder, tags and topics are last-writer-wins; card operations are checked per
 * card (§13.2) and reported in `results`. Omitted fields stay as they are; `folderId: null` moves the note out of folders.
 */
export type UpdateNoteDraftInput = {
  folderId?: string | null | undefined;
  noteId: string;
  ops?: Array<CardOpInput> | null | undefined;
  tagNames?: Array<string> | null | undefined;
  title?: string | null | undefined;
  topicIds?: Array<string> | null | undefined;
};

export type UpdatePdfHighlightInput = {
  /** null unlinks the card */
  cardId?: string | null | undefined;
  color?: HighlightColor | null | undefined;
  /** An empty comment removes it */
  comment?: string | null | undefined;
  highlightId: string;
};

/** Omitted fields stay as they are; null clears a field */
export type UpdateProfileInput = {
  department?: string | null | undefined;
  interestTopicIds?: Array<string> | null | undefined;
  showOnProfile?: boolean | null | undefined;
  yearOfStudy?: YearOfStudy | null | undefined;
};

/** Replaces the whole tab: headline (120 characters), bio (2,000) and at most 60 items in this order */
export type UpdateTeacherProfileInput = {
  bio?: string | null | undefined;
  headline?: string | null | undefined;
  skills: Array<TeacherSkillInput>;
};

export type VerificationMethod =
  | 'DOCUMENTS'
  | 'INSTITUTIONAL_EMAIL'
  | 'TEACHER';

/** Who can read a note (§4.2) */
export type Visibility =
  | 'PRIVATE'
  | 'PUBLIC'
  | 'SHARED';

export type YearOfStudy =
  | 'GRADUATED'
  | 'NOT_STUDYING'
  | 'POSTGRADUATE'
  | 'SCHOOL'
  | 'YEAR_1'
  | 'YEAR_2'
  | 'YEAR_3'
  | 'YEAR_4'
  | 'YEAR_5';

